protected Pod getPod(String podName, AppConfig.SparkCluster sparkCluster) {
    com.codahale.metrics.Timer timer = registry.timer(this.getClass().getSimpleName() + ".getPod.k8s-time");
    try (DefaultKubernetesClient client = KubernetesHelper.getK8sClient(sparkCluster);
        com.codahale.metrics.Timer.Context context = timer.time()) {
        Pod pod = client.pods().inNamespace(sparkCluster.getSparkApplicationNamespace()).withName(podName).get();
        context.stop();
        return pod;
    }
}
